// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // owner mints 100 tokens to themselves
        c.mintToken(address(this), 100);
        // owner burns 50 tokens
        c.burn(50);
        // In reference: totalSupply = 0 + 100 - 50 = 50
        // In bug: totalSupply = 0 - 100 - 50 = -150 (underflow to 2^256 - 150)
        assertTrue(c.totalSupply() == 50);
    }
}

