// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // First, call mintToken on the reference (but it's onlyOwner, so we can't, so we don't)
        // Instead, we'll exploit the bug: the buggy version allows anyone to mint.
        // We deploy both versions? No, we only have c, and we must test the contract under test.
        // But the prompt says to write one test that passes on reference and fails on bug.
        // We'll set up a scenario where the reference would revert but the buggy would not.
        // Since we can't deploy two instances, we rely on the fact that the test is run against each separately.
        // For the reference: calling burn(600) after initial deployment (with 0 supply) will revert.
        // For the buggy: if we first call mintToken (without restriction) to give owner 600, then burn succeeds.
        // However, the test is a single file; we must write a concrete scenario that exploits the difference.
        // We'll assume the test framework runs the test against the given contract (reference or buggy).
        // To make the test pass on reference and fail on buggy, we need a scenario where:
        // - On reference: burn(uint256) reverts (because totalSupply is 0 and balanceOf[msg.sender] = 0)
        // - On buggy: an attacker (not owner) calls mintToken to give themselves tokens, then calls burn, which succeeds,
        //   leading to totalSupply > 0 after burn, whereas on reference totalSupply remains 0.
        // But we cannot call mintToken on reference because it's onlyOwner and we are not owner (setUp sets owner to address(this) which is the test contract, so actually we ARE owner).
        // Wait: in setUp, owner = msg.sender = address(this) (the test contract). So we can call mintToken on reference.
        // So we need a different approach: the difference is that the buggy mintToken lacks onlyOwner, so ANYONE can call it.
        // Let's use two different callers: first, as the test contract (owner), we mint 1000 tokens to ourselves.
        // Then, as a different address (attacker), we call mintToken in the buggy version to give ourselves 1000 more,
        // then call burn(1500). On reference, the attacker cannot call mintToken (reverts due to not owner), so burn will fail (insufficient balance).
        // On buggy, the attacker can mint and then burn, making totalSupply decrease.
        // Let's implement this.
        c.mintToken(address(this), 1000); // owner mints 1000 to test contract
        uint256 totalSupplyBefore = c.totalSupply();
        vm.prank(address(0x1)); // attacker
        c.mintToken(address(0x1), 1000); // on buggy, this succeeds; on reference, reverts
        vm.prank(address(0x1));
        c.burn(1500); // attacker burns 1500 (but only has 1000 if reference, so reverts; on buggy has 1000 from mint? Actually if reference reverts on attacker's mint, attacker has 0, burn reverts.)
        // To observe difference via totalSupply: after attacker calls mintToken (if it succeeds), totalSupply increases to 2000, then burn decreases by 1500 to 500.
        // On reference, attacker's mintToken reverts, so totalSupply remains 1000 plus any change from burn? Actually burn also reverts, so totalSupply remains 1000.
        // The assertion: totalSupply should be 500 on buggy, 1000 on reference.
        // But the test is run against one contract: we want the assertion to be true for reference and false for buggy.
        // So let assertTrue(c.totalSupply() == 1000); 
        // On reference: totalSupply == 1000 -> true
        // On buggy: totalSupply == 500 -> false => fails test.
        // This matches the requirement: the property holds for reference, breaks for buggy.
        assertTrue(c.totalSupply() == 1000);
    }
}

