        // Step 1: Owner mints 100 tokens to owner (address(this))
        vm.prank(address(this));
        c.mintToken(address(this), 100);
        // Step 2: Attacker (non-owner) mints 100 tokens to owner in buggy version
        address attacker = address(0x1234);
        vm.prank(attacker);
        c.mintToken(address(this), 100);
        // Step 3: Owner burns 50 tokens
        vm.prank(address(this));
        c.burn(50);
        // Assert: In reference, only owner could mint, so totalSupply = 50 (0+100-50)
        // In buggy, attacker also minted 100, so totalSupply = 150 (0+100+100-50)
        assertTrue(c.totalSupply() < 100);
    }
}

