pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // First, owner (address(this) by default) mints 1000 tokens to itself via initial 0 supply trick: actually we need initial supply 1000, but constructor takes initialSupply 0; we use mintToken to create totalSupply.
        // However for a clean scenario, we directly deploy with initialSupply = 1000 by setting up via mintToken: owner mints 1000 to itself first.
        c.mintToken(address(this), 1000);
        // Now totalSupply = 1000, owner has 1000 tokens.
        // Owner mints 500 more to itself.
        c.mintToken(address(this), 500);
        // Now totalSupply = 1500, owner has 1500 tokens.
        // A non-owner account (address(1)) tries to mint 200 to owner:
        vm.prank(address(1));
        c.mintToken(address(this), 200);
        // In reference, this call reverts (onlyOwner), but we catch revert and continue? Actually we want the call to succeed or fail depending on version. We will burn later.
        // Instead of reverting the test, we make the mintToken call via try/catch to allow test to proceed.
        // But simpler: we can still call it directly; if reference reverts, test fails. So we need to catch revert.
        // We'll record whether non-owner mint succeeded.
        bool nonOwnerMintSucceeded;
        vm.prank(address(1));
        try c.mintToken(address(this), 200) {
            nonOwnerMintSucceeded = true;
        } catch {
            nonOwnerMintSucceeded = false;
        }
        // Owner burns 600 tokens:
        c.burn(600);
        // Now check totalSupply divergence:
        // In reference (nonOwnerMintSucceeded false), totalSupply = 1500 - 600 = 900.
        // In buggy (nonOwnerMintSucceeded true), totalSupply = 1500 + 200 - 600 = 1100.
        // Also owner balance: reference: 1500 - 600 = 900; buggy: 1500 + 200 - 600 = 1100.
        // Assert the reference value is 900.
        assertTrue(c.totalSupply() == 900);
    }
}

