pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // set up: mint initial supply to owner so burn is possible
        address alice = address(0x123);
        // owner deploys contract, gets initial supply 0 (since initialSupply=0, decimals=0)
        // We need balance for owner to burn. Use vm.prank to let owner mint to itself first.
        vm.prank(address(this)); // owner is deployer (this contract)
        c.mintToken(address(this), 1000); // now owner has 1000 tokens

        vm.prank(address(this));
        c.burn(100); // owner burns 100 tokens, totalSupply becomes 900, balanceOf[owner] becomes 900

        vm.prank(address(this));
        c.mintToken(alice, 100); // reference: balanceOf[alice] += 100 => 100; bug: balanceOf[alice] -= 100 => -100 (underflow? but solidity 0.8 reverts on underflow, so bug reverts)
        // Since the bug reverts on mintToken, we use try/catch to detect revert difference.
        bool mintSucceeded = false;
        try c.mintToken(alice, 100) { mintSucceeded = true; } catch { mintSucceeded = false; }
        // Reference: mintSucceeded = true, balanceOf[alice] = 100; Bug: mintSucceeded = false (revert).
        // Assert that mint succeeded (reference behavior). Bug will fail because mintSucceeded is false.
        assertTrue(mintSucceeded);
    }
}

