// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // Setup: owner mints tokens to a frozen account
        address frozen = address(0x123);
        c.freezeAccount(frozen, true);
        c.mintToken(frozen, 100);

        // Owner burns tokens (this internally calls _transfer from owner to address(0))
        // Owner has 0 balance initially, burn reverts for reference but not for mutant?
        // Actually burn deducts from burner's balance, not via _transfer. Let's adjust.
        // Instead: use freezeAccount on a different account then transfer from frozen through burn? No.
        // Let's design: owner mints to self, freezes self, then burn. Reference: burn deducts from owner, but frozenAccount check is in _transfer, not in burn directly. The bug removed _from frozen check in _transfer, which is called by transfer, not burn. So burn won't diverge. We need a transfer scenario.
        // Correct scenario: owner mints to self, then transfer to a frozen recipient? That uses _to check. We need _from frozen.
        // Owner mints to frozen account, then frozen account transfers (via prank) to another. 
        // Reference: frozen account cannot transfer (revert due to frozenAccount[_from] check). Mutant: can transfer.

        // Reset and redo:
        C c2 = new C(0, "", "");
        address alice = address(0x1);
        c2.mintToken(alice, 100);
        c2.freezeAccount(alice, true);
        // Alice tries to transfer
        bool ok = false;
        try c2.transfer(address(0x2), 50) { ok = true; } catch { ok = false; }
        // Reference: ok == false because alice frozen. Mutant: ok == true.
        // But we need to use the same c instance as in setUp.
        // Let's use the actual c: after setUp, totalSupply is 0. So we must mint.
        c.mintToken(address(this), 100);
        vm.prank(address(this));
        c.transfer(address(0xdead), 50); // this works
        // Now freeze this contract and try again
        c.freezeAccount(address(this), true);
        bool success = false;
        try c.transfer(address(0xbeef), 10) { success = true; } catch { success = false; }
        // Reference: success == false; Mutant: success == true.
        assertTrue(!success, "Frozen account should not be able to transfer");
