pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(100, "Test", "TST"); }
    function testRegression_property() public {
        address nonOwner = address(0x1234);
        vm.deal(nonOwner, 1 ether);

        // Mint tokens to nonOwner so they have a balance (but owner stays with 100)
        vm.prank(c.owner());
        c.mintToken(nonOwner, 200);

        // Now nonOwner (not owner) tries to call burn (which is onlyOwner, so it will revert at the modifier)
        // Actually, we need the owner to call burn with an amount greater than their balance.
        // Owner has 100 tokens, totalSupply is 300. Attempt burn(200).
        vm.prank(c.owner());

        bool ok;
        try c.burn(200) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference (with require) reverts, so ok == false.
        // Buggy (without require) succeeds, so ok == true.
        // Here we assert that the call does NOT revert (i.e., the buggy behavior).
        // Since the buggy succeeds, this will fail on the reference and pass on the bug.
        assertTrue(ok);
    }
}

